"""Settings the user changes at run time (D-054): the OpenAI API key and the budget limits.

Stored in `$DATA_DIR/settings.json` (git-ignored, owner-only 0600), outside `app.db` so a snapshot restore never
touches it. `APP_SETTINGS_FILE` overrides the path (tests point it at a temp file).

- API key: the key saved here wins over `OPENAI_API_KEY` from `.env` / the environment. Never returned in full —
  callers show `mask()`.
- Budget (on committed spend = settled cost + open reservations, see `llm.budget`):
  `confirm_above_usd` — above this, a run must be confirmed before it spends (terminal prompt or the app's confirm);
  `stop_at_usd` — hard stop, no call may cross it.
"""

from __future__ import annotations

import json
import os
import threading
from dataclasses import dataclass
from pathlib import Path

from bmw_req.config import get_settings

DEFAULT_CONFIRM_ABOVE_USD = 45.0
DEFAULT_STOP_AT_USD = 90.0
MAX_STOP_AT_USD = 10_000.0

_LOCK = threading.Lock()


@dataclass(frozen=True)
class BudgetLimits:
    confirm_above_usd: float
    stop_at_usd: float


def path() -> Path:
    override = os.getenv("APP_SETTINGS_FILE")
    return Path(override) if override else get_settings().data_dir / "settings.json"


def load() -> dict:
    try:
        data = json.loads(path().read_text())
    except (FileNotFoundError, json.JSONDecodeError):
        return {}
    return data if isinstance(data, dict) else {}


def _save(data: dict) -> None:
    p = path()
    p.parent.mkdir(parents=True, exist_ok=True)
    tmp = p.with_suffix(".tmp")
    fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "w") as f:
        json.dump(data, f, indent=1)
    os.replace(tmp, p)
    os.chmod(p, 0o600)


def _update(**changes) -> None:
    with _LOCK:
        data = load()
        for k, v in changes.items():
            if v is None:
                data.pop(k, None)
            else:
                data[k] = v
        _save(data)


# ------------------------------------------------------------------------------------------------ API key
def api_key() -> str | None:
    return load().get("openai_api_key") or get_settings().openai_api_key or None


def key_source() -> str | None:
    """'app' (saved in settings.json), 'env' (.env / environment) or None."""
    if load().get("openai_api_key"):
        return "app"
    return "env" if get_settings().openai_api_key else None


def mask(key: str | None) -> str | None:
    if not key:
        return None
    return f"{key[:3]}…{key[-4:]}" if len(key) > 10 else "…"


def set_api_key(key: str | None) -> None:
    """Save the key (None removes it, falling back to `.env`)."""
    key = (key or "").strip() or None
    if key is not None and (len(key) < 20 or any(c.isspace() for c in key)):
        raise ValueError("That doesn't look like an OpenAI API key.")
    _update(openai_api_key=key)


# ------------------------------------------------------------------------------------------------ budget
def budget_limits() -> BudgetLimits:
    b = load().get("budget") or {}
    return BudgetLimits(float(b.get("confirm_above_usd", DEFAULT_CONFIRM_ABOVE_USD)),
                        float(b.get("stop_at_usd", DEFAULT_STOP_AT_USD)))


def set_budget_limits(confirm_above_usd: float, stop_at_usd: float) -> BudgetLimits:
    if not 0 < stop_at_usd <= MAX_STOP_AT_USD:
        raise ValueError(f"The stop must be between $0 and ${MAX_STOP_AT_USD:,.0f}.")
    if not 0 <= confirm_above_usd <= stop_at_usd:
        raise ValueError("Ask-before-spending must be between $0 and the stop.")
    limits = BudgetLimits(round(confirm_above_usd, 2), round(stop_at_usd, 2))
    _update(budget={"confirm_above_usd": limits.confirm_above_usd, "stop_at_usd": limits.stop_at_usd})
    return limits

"""Run-time settings (D-054): the OpenAI API key and the budget limits, set from the app's Usage tab.

The key is never returned — only whether one is set, where it comes from and a masked form. Saving a key first checks
it against OpenAI with a free call (`models.list`). Every change is an audit event (AGENTS rule 6); the key itself is
never written to the audit trail, only its masked form.
"""

from __future__ import annotations

import openai
from fastapi import APIRouter, Depends, HTTPException
from pydantic import BaseModel

from api.deps import db, get_actor
from bmw_req import app_settings
from bmw_req.llm import budget
from bmw_req.pipeline.requirements import audit

router = APIRouter(prefix="/api/settings", tags=["settings"])


class KeyBody(BaseModel):
    key: str


class BudgetBody(BaseModel):
    confirm_above_usd: float
    stop_at_usd: float


def _state() -> dict:
    limits = app_settings.budget_limits()
    with db() as conn:
        spent, committed = budget.spent_usd(conn), budget.committed_usd(conn)
    return {
        "openai": {"configured": app_settings.api_key() is not None, "source": app_settings.key_source(),
                   "masked": app_settings.mask(app_settings.api_key())},
        "budget": {"confirm_above_usd": limits.confirm_above_usd, "stop_at_usd": limits.stop_at_usd,
                   "spent_usd": round(spent, 4), "committed_usd": round(committed, 4),
                   "asking": committed > limits.confirm_above_usd, "stopped": committed >= limits.stop_at_usd},
    }


def verify_key(key: str) -> None:
    """Free check that OpenAI accepts the key (raises HTTP 400 if not). Patched in tests."""
    try:
        openai.OpenAI(api_key=key, timeout=10, max_retries=0).models.list()
    except openai.AuthenticationError as e:
        raise HTTPException(400, "OpenAI rejected this key.") from e
    except openai.APIError as e:
        raise HTTPException(502, f"Couldn't reach OpenAI to check the key ({type(e).__name__}); nothing was saved.") from e


@router.get("")
def get_settings() -> dict:
    return _state()


@router.put("/openai-key")
def set_key(body: KeyBody, actor: str = Depends(get_actor)) -> dict:
    key = body.key.strip()
    try:
        app_settings.set_api_key(key)   # format check first, before the network call
        app_settings.set_api_key(None)
    except ValueError as e:
        raise HTTPException(400, str(e)) from e
    old = app_settings.mask(app_settings.api_key())
    verify_key(key)
    app_settings.set_api_key(key)
    with db() as conn:
        audit(conn, actor_type="human", actor_id=actor, action="set_api_key", entity_type="setting",
              entity_id="openai_api_key", old=old, new=app_settings.mask(key), rationale="Key checked with OpenAI")
    return _state()


@router.delete("/openai-key")
def remove_key(actor: str = Depends(get_actor)) -> dict:
    old = app_settings.mask(app_settings.load().get("openai_api_key"))
    app_settings.set_api_key(None)
    with db() as conn:
        audit(conn, actor_type="human", actor_id=actor, action="remove_api_key", entity_type="setting",
              entity_id="openai_api_key", old=old, new=app_settings.mask(app_settings.api_key()),
              rationale="Falls back to OPENAI_API_KEY from .env")
    return _state()


@router.put("/budget")
def set_budget(body: BudgetBody, actor: str = Depends(get_actor)) -> dict:
    old = app_settings.budget_limits()
    try:
        new = app_settings.set_budget_limits(body.confirm_above_usd, body.stop_at_usd)
    except ValueError as e:
        raise HTTPException(400, str(e)) from e
    with db() as conn:
        audit(conn, actor_type="human", actor_id=actor, action="set_budget", entity_type="setting",
              entity_id="budget", old={"confirm_above_usd": old.confirm_above_usd, "stop_at_usd": old.stop_at_usd},
              new={"confirm_above_usd": new.confirm_above_usd, "stop_at_usd": new.stop_at_usd})
    return _state()

